      "Ray 由 UC Berkeley RISELab 开发，是当前最主流的分布式 ML 训练和推理框架之一，Anyscale（已被 NVIDIA 收购）维护的企业版被亚马逊、苹果、OpenAI 等用于扩展 ML 工作负载。漏洞存在于 Ray 的默认配置中，无需认证即可利用。",
      "Wiz 研究团队最早发现并报告了该漏洞，概念验证（PoC）代码已在互联网公开，具体利用方式已被多个威胁行为者在野使用。考虑到受影响目标包括头部云厂商和 AI 公司，这是 2026 年 AI 供应链最具影响力的安全事件之一。",
