      "对 AI + 科学研究者：蛋白质binder设计的 wet-lab 验证（22-35% vs 10-15%）是 AI4Science 领域的重大里程碑；化学分析加速（23/19 分钟 vs 传统数小时）意味着 AI 将显著降低药物发现的时间成本；建议生物/化学方向研究者关注 Anthropic 科学家访问计划的申请窗口。",
