      "对开发者：1M上下文是把双刃剑——适合需要保持大量代码/对话历史的长期项目，但成本和性能衰减需权衡；建议先用默认配置跑通任务，有真实需求再切换到1M窗口，同时关注Tibo后续的Astra集成公告。",
