    id: "2026-08-16-zhizhi-swd-sparse-weight-decomposition",
    date: "2026-08-16",
    category: "研究前沿",
    title: "至知研究院提出稀疏权重分解 SWD：拆权重做可解释性，数据成本不到基线 1%",
    summary: "至知创新研究院联合 Safe AI Forum、牛津、斯坦福、清华提出稀疏权重分解方法 SWD，直接从预训练权重中拆出可干预单元，无需训练替代网络；数据成本不到 Transcoder 等基线的 1%，并在 GPT-2、Qwen2.5、Qwen3.5-27B 上完成回路验证。",
    source: "量子位",
    url: "https://www.qbitai.com/2026/08/473876.html",
    tags: ["至知研究院", "可解释性", "稀疏权重分解", "SWD", "机制解释"],
    body: [
      "至知创新研究院联合 Safe AI Forum、牛津大学、斯坦福大学与清华大学提出稀疏权重分解（Sparse Weight Decomposition，简称 SWD）方法，直接从预训练权重中『拆』出可干预单元，不需要再训练一个替代网络（Transcoder / SAE）来近似原模型行为。",
      "在匹配替换保真度的实验中，SWD 的数据成本不到 Transcoder 等训练型基线的 1%。研究在 GPT-2、Qwen2.5 与 Qwen3.5-27B 三个不同规模模型上完成了任务回路验证，表明该方法可作为大规模机制可解释性（mechanistic interpretability）的低门槛入口。",
      "方法核心是把稠密权重矩阵分解为两个稀疏因子，共享中间坐标成为可独立评分、选择、消融的『瓶颈单元』。相比基于特征归因、LogitLens 或稀疏自编码器的方案，SWD 不依赖下游任务的标注语料，理论上对任意预训练模型都适用。",
      "对研究者：SWD 把『机制可解释性』从『只能在小模型做演示』推进到『可在 27B 级别模型做回路分析』，门槛显著降低；建议关注其官方实现仓库与论文复现细节，在安全审计、模型编辑（model editing）、可解释性评估三个方向优先试用。",
    ],
    highlights: [
      "无需训练替代网络，数据成本不到基线的 1%",
      "已在 GPT-2、Qwen2.5、Qwen3.5-27B 三个规模验证回路",
      "由至知联合 Safe AI Forum、牛津、斯坦福、清华共同提出",
    ],
