      "该水印方案基于 Google DeepMind 的 SynthID-Text 技术，通过在模型词汇选择层面嵌入统计信号实现：水印不影响输出质量、创造力或可读性，读者无法区分带水印与不带水印的文本，且不增加额外 token 或成本。",
